test("stops contracting inference waves after minVerifiedCandidates is satisfied", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let dispatchCount = 0;
  const dispatch = async (jobs) => {
    dispatchCount += 1;
    return jobs.map((job) => response(job, { action: "read", args: { path: "calc.mjs" }, reason: "inspect" }));
  };
  const result = await runMission({
    id: "urn:test:quorum",
    objective: "Test quorum",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 2,
    maxRounds: 5,
    minVerifiedCandidates: 1,
  }, { dispatch, ledgerRoot });
  assert.equal(dispatchCount, 1);
});

test("runMission stops dispatching after minVerifiedCandidates is satisfied", async () => {
  const territory = fixture();
  let dispatchCount = 0;
  const dispatch = async (jobs) => {
    dispatchCount += 1;
    return jobs.map((job) => response(job, { action: "read", args: { path: "calc.mjs" }, reason: "just inspect" }));
  };
  const result = await runMission({
    id: "urn:test:mission:quorum",
    objective: "Always pass.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 2,
    maxRounds: 5,
    minVerifiedCandidates: 1,
    apply: false,
  }, { dispatch });

  assert.equal(result.outcome.verified, true);
  assert.equal(dispatchCount, 1, "Should stop dispatching after minVerifiedCandidates met");
});

